package com.savora.api; import java.util.*; public record Api<T>(T data,String message){public static <T> Api<T> ok(T d){return new Api<>(d,"OK");}} record Auth(String accessToken,String refreshToken,UserDto user){} record UserDto(Long id,String name,String email,String phone,String role,String avatar){} record Credentials(@jakarta.validation.constraints.Email String email,@jakarta.validation.constraints.NotBlank String password){} record Register(@jakarta.validation.constraints.NotBlank String name,@jakarta.validation.constraints.Email String email,@jakarta.validation.constraints.Size(min=8) String password,String phone){} record CartLine(Long foodId,@jakarta.validation.constraints.Min(1) int quantity){} record Checkout(List<CartLine> items,Long addressId,String coupon){} 
